  const statCard = (label,value,icon,note,extra='') => `<article class="admin-card stat-card"><div class="stat-top"><span class="stat-label">${esc(label)}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${esc(value)}</div><div class="stat-note">${note||''}</div>${extra}</article>`;
  function chartSVG(labels, values, mode='area') {
    if(!values?.length) return '<div class="chart-placeholder">Henüz görüntülenme verisi oluşmadı.</div>';
    const width=740,height=230,left=36,right=16,top=16,bottom=36,plotW=width-left-right,plotH=height-top-bottom;
    const max=Math.max(4,...values); const points=values.map((v,i)=>({x:left+(values.length===1?plotW/2:i*plotW/(values.length-1)),y:top+plotH-(v/max)*plotH,v}));
    const poly=points.map(p=>`${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ');
    const area=`${left},${top+plotH} ${poly} ${left+plotW},${top+plotH}`;
    const grid=[0,.33,.66,1].map(t=>{const y=top+plotH*(1-t);return `<line x1="${left}" y1="${y}" x2="${left+plotW}" y2="${y}" stroke="#edf1f6" stroke-width="1"/><text x="${left-9}" y="${y+4}" text-anchor="end" fill="#91a0b1" font-size="9">${Math.round(max*t)}</text>`}).join('');
    const step=Math.max(1,Math.ceil(labels.length/6));
    const labelText=points.map((p,i)=>i%step===0||i===points.length-1?`<text x="${p.x}" y="${height-12}" text-anchor="middle" fill="#91a0b1" font-size="9">${esc(String(labels[i]).slice(mode==='year'?2:5))}</text>`:'').join('');
    const dots=points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="3" fill="#fff" stroke="#2762ad" stroke-width="2"><title>${p.v}</title></circle>`).join('');
    return `<svg class="chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="Zamana göre istatistik grafiği">${grid}<defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#2d6dbb" stop-opacity=".23"/><stop offset="1" stop-color="#2d6dbb" stop-opacity=".01"/></linearGradient></defs><polygon points="${area}" fill="url(#chartFill)"/><polyline points="${poly}" fill="none" stroke="#2863ad" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${dots}${labelText}</svg>`;
  }
  function periodSwitch(period, target='stats-period') { return `<div class="period-switch" data-period-group="${target}"><button type="button" data-period="week" class="${period==='week'?'is-active':''}">Hafta</button><button type="button" data-period="month" class="${period==='month'?'is-active':''}">Ay</button><button type="button" data-period="year" class="${period==='year'?'is-active':''}">Yıl</button></div>`; }
