      const list = Array.isArray(r.districts) ? r.districts : [];
      ds.innerHTML = '<option value="">İlçe seçin</option>' + list.map(d => `<option value="${esc(d.name)}" ${d.name === keepD ? 'selected' : ''}>${esc(d.name)}</option>`).join('');
