      + `<section class="admin-card form-section"><header class="form-section-head"><div><h2>Google Search Console</h2><p>Site sahipliği doğrulama kodu ve self link modu. Self link kapalıyken canonical basılmaz; localde kapalı tutun, canlıda açın.</p></div></header><div class="form-section-body"><div class="form-grid">${field('google_site_verification','Doğrulama kodu',val('google_site_verification'),'text',{full:true,maxlength:300,placeholder:'Search Console HTML etiketindeki content kodu',help:'Search Console > Mülk ekle > HTML etiketi yöntemindeki content değerini yapıştırın. Tam meta etiketini de yapıştırabilirsiniz.'})}<div class="form-field"><label>Self link modu (canlı)</label><div class="checkbox-row"><input id="seoSelfLinks" name="seo_self_links" type="checkbox" value="1" ${val('seo_self_links','0')==='1'?'checked':''}><label for="seoSelfLinks" style="margin:0">Açık: canonical ve self link üret</label></div></div></div></div></section>`
      + `<section class="admin-card form-section"><header class="form-section-head"><div><h2>Sayfa SEO başlık ve açıklamaları</h2><p>Boş bırakılan alanlar sistem tarafından otomatik üretilir.</p></div></header><div class="form-section-body"><div class="form-grid">${field('seo_home_title','Anasayfa SEO başlığı',val('seo_home_title'),'text',{full:true,maxlength:70,help:'Önerilen uzunluk 30-65 karakter.'})}${field('seo_home_description','Anasayfa meta açıklaması',val('seo_home_description'),'textarea',{full:true,maxlength:200,help:'Önerilen uzunluk 100-180 karakter.'})}${field('seo_about_title','Hakkımızda SEO başlığı',val('seo_about_title'),'text',{full:true,maxlength:70})}${field('seo_about_description','Hakkımızda meta açıklaması',val('seo_about_description'),'textarea',{full:true,maxlength:200})}${field('seo_contact_title','İletişim SEO başlığı',val('seo_contact_title'),'text',{full:true,maxlength:70})}${field('seo_contact_description','İletişim meta açıklaması',val('seo_contact_description'),'textarea',{full:true,maxlength:200})}</div></div></section>`
      + `<section class="admin-card form-section"><header class="form-section-head"><div><h2>Arama motoru bildirimi (IndexNow)</h2><p>Yayınlanan ilanlar Bing ve Yandex'e otomatik bildirilir. Google için Search Console manuel kullanılır.</p></div><span class="status-pill ${val('indexnow_enabled','0')==='1'?'status-active':'status-draft'}" id="indexnowState">${val('indexnow_enabled','0')==='1'?'Otomatik bildirim açık':'Kapalı'}</span></header><div class="form-section-body"><div class="form-grid"><div class="form-field"><label>Otomatik bildirim</label><div class="checkbox-row"><input type="checkbox" id="indexnowEnabled" name="indexnow_enabled" value="1" ${val('indexnow_enabled','0')==='1'?'checked':''}><label for="indexnowEnabled" style="margin:0">Yayınlanan ilanları otomatik bildir</label></div></div>${field('indexnow_key','IndexNow anahtarı',val('indexnow_key'),'text',{full:true,maxlength:64,placeholder:'32 haneli anahtar',help:'Üret butonuyla oluşturun; anahtar dosyası site kök dizinine otomatik yazılır.'})}<div class="form-field full"><label>Manuel bildirim</label><div class="indexnow-row"><button class="admin-btn admin-btn-outline admin-btn-sm" type="button" id="indexnowGen">Anahtar üret</button><button class="admin-btn admin-btn-outline admin-btn-sm" type="button" id="indexnowTest">Bağlantıyı dene</button><button class="admin-btn admin-btn-primary admin-btn-sm" type="button" id="indexnowAll">Tümünü bildir</button></div><small id="indexnowStatus">${esc(val('indexnow_last','Henüz bildirim yapılmadı.'))}</small></div></div></div></section>`
      + `<div class="form-bottom-actions"><button class="admin-btn admin-btn-primary" type="submit">Ayarları kaydet →</button></div></form>`;
    root.innerHTML=h;
