    document.getElementById('indexnowGen')?.addEventListener('click',()=>{const inp=document.getElementById('field_indexnow_key');if(!inp)return;const b=new Uint8Array(16);crypto.getRandomValues(b);inp.value=[...b].map(x=>x.toString(16).padStart(2,'0')).join('');toast('Yeni anahtar üretildi. Kaydetmeyi unutmayın.');});
    const ixPing=(scope)=>{req('indexnow_ping',{scope},{method:'POST'}).then(r=>{toast(r.message);const st=document.getElementById('indexnowStatus');if(st&&r.summary)st.textContent=r.summary;}).catch(err=>toast(err.message,'error'));};
